11	// Widen any verilator signal type to uint64_t.
12	// Scalars (bool/u8/u32/u64) widen via static_cast.
13	// VlWide<N> (m_storage array): take low 64 bits.
14	template<typename T>
15	uint64_t widen_to_u64(const T& v)
16	{
17	  if constexpr (std::is_convertible_v<T, uint64_t>)
18	    return static_cast<uint64_t>(v);
19	  else // VlWide<N>
20	    return (static_cast<uint64_t>(v.m_storage[1]) << 32)
21	         | static_cast<uint64_t>(v.m_storage[0]);
22	}
