24	template<typename Derived>
25	class CpuSignalRegistry
26	{
27	public:
28	  // Stateless lambdas decay to function pointers — no std::function overhead.
29	  using SignalAccessor = uint64_t (*)(const Derived&);
30	  using Registry = std::unordered_map<std::string, SignalAccessor>;
31	
32	  uint64_t get_signal(const std::string& name) const
33	  {
34	    auto it = registry().find(name);
35	    if (it == registry().end())
36	      throw std::runtime_error("Unknown signal: " + name);
37	    return it->second(static_cast<const Derived&>(*this));
38	  }
39	
40	  bool has_signal(const std::string& name) const
41	  {
42	    return registry().contains(name);
43	  }
44	
45	  std::vector<std::string> list_signals() const
46	  {
47	    std::vector<std::string> out;
48	    out.reserve(registry().size());
49	    for (auto& [k, _]: registry())
50	      out.push_back(k);
51	    return out;
52	  }
53	
54	#if ENABLE_PYBIND11
55	  static void bind_registry_to_pybind11(pybind11::class_<Derived>& c)
56	  {
57	    for (auto& [name, accessor]: registry())
58	      c.def_property_readonly(name.c_str(), accessor);
59	  }
60	#endif
61	
62	protected:
63	  // Each Derived class must implement:
64	  //   static Registry build_signal_registry();
65	
66	private:
67	  static const Registry& registry()
68	  {
69	    static const Registry reg = Derived::build_signal_registry();
70	    return reg;
71	  }
72	};
